import { test, expect } from '@playwright/test'
import { ADMIN_AUTH, API_BASE, WEB_BASE } from '../auth.helpers'

// ── US2: Board member adds and manages cards ──────────────────────────────────

test.describe('US2: Board member adds and manages cards', () => {
  test.use({ storageState: ADMIN_AUTH })

  test('scenario 1 — member adds a card to a lane and it appears', async ({ page, request }) => {
    const boardName = `Card Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })
    expect(boardResp.ok()).toBeTruthy()
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'To Do' },
    })
    expect(laneResp.ok()).toBeTruthy()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByRole('heading', { name: boardName })).toBeVisible({ timeout: 10_000 })

    await page.getByRole('button', { name: /add card/i }).first().click()
    await page.getByRole('textbox', { name: /card title/i }).fill('My First Card')
    await page.getByRole('button', { name: /^add$/i }).click()

    await expect(page.getByText('My First Card')).toBeVisible({ timeout: 10_000 })
  })

  test('scenario 2 — member updates title, description, and due date', async ({
    page,
    request,
  }) => {
    const boardName = `Update Card Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Work' },
    })
    const lane = await laneResp.json()
    const cardResp = await request.post(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
      { data: { title: 'Original Title' } },
    )
    expect(cardResp.ok()).toBeTruthy()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByText('Original Title')).toBeVisible({ timeout: 10_000 })

    await page.getByRole('button', { name: /edit card/i }).first().click()
    await page.getByRole('textbox', { name: /title/i }).fill('Updated Title')
    await page.getByRole('textbox', { name: /description/i }).fill('A new description')
    await page.getByRole('button', { name: /save/i }).click()

    await expect(page.getByText('Updated Title')).toBeVisible({ timeout: 10_000 })
  })

  test('scenario 3 — member explicitly clears a card due date', async ({ page, request }) => {
    const boardName = `Due Date Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Work' },
    })
    const lane = await laneResp.json()
    const cardResp = await request.post(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
      { data: { title: 'Task With Due Date', dueDate: '2099-12-31' } },
    )
    expect(cardResp.ok()).toBeTruthy()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByText('Task With Due Date')).toBeVisible({ timeout: 10_000 })

    await page.getByRole('button', { name: /edit card/i }).first().click()
    await page.getByRole('checkbox', { name: /clear due date/i }).check()
    await page.getByRole('button', { name: /save/i }).click()
    // not.toBeAttached waits for the Fluent UI dialog portal to be fully removed
    // from the DOM (not just hidden), at which point its backdrop no longer blocks
    // pointer events on the cards behind it.
    await expect(page.getByRole('dialog')).not.toBeAttached({ timeout: 10_000 })

    await page.getByRole('button', { name: /edit card/i }).first().click()
    const dueDateField = page.getByRole('textbox', { name: /due date/i })
    await expect(dueDateField).toHaveValue('')
  })

  test('scenario 4 — delete card leaves remaining positions gapless', async ({
    page,
    request,
  }) => {
    const boardName = `Delete Card Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Work' },
    })
    const lane = await laneResp.json()
    for (const title of ['Card Alpha', 'Card Beta', 'Card Gamma']) {
      const resp = await request.post(
        `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
        { data: { title } },
      )
      expect(resp.ok()).toBeTruthy()
    }

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByText('Card Alpha')).toBeVisible({ timeout: 10_000 })

    await page.getByRole('button', { name: /delete card/i }).first().click()
    await expect(page.getByRole('dialog')).toBeVisible({ timeout: 5_000 })
    await page.getByRole('button', { name: /confirm/i }).click()
    await expect(page.getByRole('dialog')).not.toBeAttached({ timeout: 10_000 })

    await expect(page.getByText('Card Alpha')).not.toBeVisible()
    await expect(page.getByText('Card Beta')).toBeVisible()
    await expect(page.getByText('Card Gamma')).toBeVisible()

    // Verify gapless positions via API
    const boardDetailResp = await request.get(`${API_BASE}/api/v1/boards/${board.id}`)
    const boardDetail = await boardDetailResp.json()
    const positions = boardDetail.lanes[0].cards.map((c: { position: number }) => c.position)
    expect(positions).toEqual([1, 2])
  })

  test('scenario 5 — viewer role add-card request returns 403', async ({ request, browser }) => {
    const viewerEmail = `e2e-viewer-${Date.now()}@example.com`

    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: `Viewer Forbidden Board ${Date.now()}` },
    })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Lane' },
    })
    const lane = await laneResp.json()

    // Add viewer to the board via dev seed endpoint (implemented alongside CardEndpoints)
    const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed-board-member`, {
      data: { email: viewerEmail, boardId: board.id, role: 'Viewer' },
    })
    expect(seedResp.ok()).toBeTruthy()

    const viewerCtx = await browser.newContext()
    const viewerPage = await viewerCtx.newPage()
    await viewerPage.goto(
      `${API_BASE}/api/v1/dev/authenticate?email=${encodeURIComponent(viewerEmail)}&displayName=Viewer+User`,
    )
    await viewerPage.waitForURL(`${WEB_BASE}/**`)

    const forbiddenResp = await viewerPage.request.post(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
      { data: { title: 'Viewer Should Not Create This' } },
    )
    expect(forbiddenResp.status()).toBe(403)

    await viewerCtx.close()
  })

  test.skip('scenario 6 — empty card title is rejected with validation error', async ({
    page,
    request,
  }) => {
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: `Title Val Board ${Date.now()}` },
    })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Lane' },
    })
    expect(laneResp.ok()).toBeTruthy()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByRole('heading', { name: board.name })).toBeVisible({ timeout: 10_000 })
    await expect(page.getByText('Lane')).toBeVisible({ timeout: 10_000 })

    await page.getByRole('button', { name: /add card/i }).first().click()
    await page.getByRole('textbox', { name: /card title/i }).fill('')
    await page.getByRole('button', { name: /^add$/i }).click()

    await expect(page.getByRole('alert')).toBeVisible({ timeout: 10_000 })
  })
})

import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { Button, Text, Badge, makeStyles, tokens } from '@fluentui/react-components'
import { NoteRegular } from '@fluentui/react-icons'
import type { Card } from '../../hooks/useBoard'
import type { BoardRole } from '../../hooks/useBoards'

const useStyles = makeStyles({
  card: {
    backgroundColor: tokens.colorNeutralBackground1,
    borderRadius: tokens.borderRadiusMedium,
    padding: tokens.spacingVerticalS,
    paddingLeft: tokens.spacingHorizontalM,
    paddingRight: tokens.spacingHorizontalS,
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    gap: tokens.spacingHorizontalS,
    boxShadow: tokens.shadow2,
    cursor: 'grab',
    touchAction: 'none',
  },
  cardGhost: {
    opacity: 0.4,
  },
  cardViewer: {
    cursor: 'default',
  },
  body: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalXS,
    flex: 1,
    minWidth: 0,
  },
  meta: {
    display: 'flex',
    alignItems: 'center',
    gap: tokens.spacingHorizontalXS,
  },
})

interface CardItemProps {
  card: Card
  callerRole: BoardRole
  dragInstructionsId?: string
  onEdit: (card: Card) => void
  onDelete: (card: Card) => void
}

export default function CardItem({
  card,
  callerRole,
  dragInstructionsId,
  onEdit,
  onDelete,
}: CardItemProps) {
  const styles = useStyles()
  const canModify = callerRole === 'Owner' || callerRole === 'Member'

  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: card.id,
    disabled: !canModify,
  })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition: transition ?? undefined,
  }

  const describedBy = dragInstructionsId ? { 'aria-describedby': dragInstructionsId } : {}

  return (
    <article
      ref={setNodeRef}
      className={`${styles.card}${isDragging ? ` ${styles.cardGhost}` : ''}${!canModify ? ` ${styles.cardViewer}` : ''}`}
      style={style}
      {...attributes}
      {...(canModify ? listeners : {})}
      {...describedBy}
      {...(canModify ? { 'data-drag-handle': '' } : {})}
    >
      <div className={styles.body}>
        <Text>{card.title}</Text>
        <div className={styles.meta}>
          {card.dueDate && (
            <Badge appearance="outline" size="small">
              {card.dueDate}
            </Badge>
          )}
          {card.description && (
            <span role="img" aria-label="has description">
              <NoteRegular fontSize={14} aria-hidden="true" />
            </span>
          )}
        </div>
      </div>
      {canModify && (
        <>
          <Button
            size="small"
            appearance="subtle"
            aria-label={`Edit card ${card.title}`}
            onClick={() => onEdit(card)}
          >
            Edit
          </Button>
          <Button
            size="small"
            appearance="subtle"
            aria-label={`Delete card ${card.title}`}
            onClick={() => onDelete(card)}
          >
            Delete card
          </Button>
        </>
      )}
    </article>
  )
}

import { useId, useRef, useState } from 'react'
import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  closestCenter,
} from '@dnd-kit/core'
import type { DragEndEvent, DragStartEvent } from '@dnd-kit/core'
import {
  SortableContext,
  horizontalListSortingStrategy,
  sortableKeyboardCoordinates,
} from '@dnd-kit/sortable'
import { makeStyles, tokens } from '@fluentui/react-components'
import type { BoardDetail, Card, Lane as LaneData } from '../../hooks/useBoard'
import { useMoveCard } from '../../hooks/useMoveCard'
import { useMoveLane } from '../../hooks/useMoveLane'
import Lane from './Lane'
import CardDragPreview from './CardDragPreview'
import LaneDragPreview from './LaneDragPreview'
import AddLaneForm from './AddLaneForm'
import { useDeleteLane } from '../../hooks/useDeleteLane'

const useStyles = makeStyles({
  lanes: {
    display: 'flex',
    gap: tokens.spacingHorizontalM,
    alignItems: 'flex-start',
    overflowX: 'auto',
    paddingBottom: tokens.spacingVerticalM,
  },
  instructions: {
    position: 'absolute',
    width: '1px',
    height: '1px',
    padding: '0',
    margin: '-1px',
    overflow: 'hidden',
    clip: 'rect(0,0,0,0)',
    whiteSpace: 'nowrap',
    border: '0',
  },
})

interface KanbanBoardProps {
  board: BoardDetail
}

type ActiveItem = { type: 'card'; item: Card } | { type: 'lane'; item: LaneData } | null

export default function KanbanBoard({ board }: KanbanBoardProps) {
  const styles = useStyles()
  const instructionsId = useId()
  const [activeItem, setActiveItem] = useState<ActiveItem>(null)
  const activeRef = useRef<ActiveItem>(null)

  const canModify = board.callerRole === 'Owner' || board.callerRole === 'Member'

  const moveCard = useMoveCard()
  const moveLane = useMoveLane()
  const deleteLane = useDeleteLane()

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  )

  const sortedLanes = [...board.lanes].sort((a, b) => a.position - b.position)
  const laneIds = sortedLanes.map((l) => l.id)

  const handleDragStart = ({ active }: DragStartEvent) => {
    const card = board.lanes.flatMap((l) => l.cards).find((c) => c.id === active.id)
    if (card) {
      const next: ActiveItem = { type: 'card', item: card }
      setActiveItem(next)
      activeRef.current = next
      return
    }
    const lane = board.lanes.find((l) => l.id === active.id)
    if (lane) {
      const next: ActiveItem = { type: 'lane', item: lane }
      setActiveItem(next)
      activeRef.current = next
    }
  }

  const handleDragEnd = ({ active, over }: DragEndEvent) => {
    setActiveItem(null)
    activeRef.current = null
    if (!over || active.id === over.id) return

    const draggingCard = board.lanes.flatMap((l) => l.cards).find((c) => c.id === active.id)
    if (draggingCard) {
      // Determine target lane and position
      const overCard = board.lanes.flatMap((l) => l.cards).find((c) => c.id === over.id)
      const overLane = board.lanes.find((l) => l.id === over.id)
      const targetLaneId = overCard?.laneId ?? overLane?.id ?? draggingCard.laneId
      const targetLane = board.lanes.find((l) => l.id === targetLaneId)
      if (!targetLane) return
      const targetPosition = overCard ? overCard.position : targetLane.cards.length + 1
      moveCard.mutate({
        boardId: board.id,
        cardId: draggingCard.id,
        targetLaneId,
        targetPosition,
        expectedVersion: draggingCard.version,
      })
      return
    }

    const draggingLane = board.lanes.find((l) => l.id === active.id)
    if (draggingLane) {
      const overLane = board.lanes.find((l) => l.id === over.id)
      if (!overLane) return
      moveLane.mutate({
        boardId: board.id,
        laneId: draggingLane.id,
        targetPosition: overLane.position,
        expectedVersion: draggingLane.version,
      })
    }
  }

  const announcements = {
    onDragStart: ({ active }: DragStartEvent) =>
      `Picked up item ${active.id}. Use arrow keys to move, Space to drop, Escape to cancel.`,
    onDragOver: () => ``,
    onDragEnd: ({ active, over }: DragEndEvent) =>
      over ? `Dropped ${active.id} at position near ${over.id}.` : `Drop cancelled.`,
    onDragCancel: ({ active }: DragStartEvent) => `Move cancelled for ${active.id}.`,
  }

  return (
    <>
      <span id={instructionsId + '-drag-instructions'} className={styles.instructions}>
        Press Space or Enter to start dragging. Use arrow keys to move. Press Space or Enter to
        drop, or Escape to cancel.
      </span>
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
        accessibility={{ announcements }}
      >
        <SortableContext items={laneIds} strategy={horizontalListSortingStrategy}>
          <div className={styles.lanes}>
            {sortedLanes.map((lane) => (
              <Lane
                key={lane.id}
                lane={lane}
                callerRole={board.callerRole}
                dragInstructionsId={instructionsId + '-drag-instructions'}
                onDelete={(bId, lId) => deleteLane.mutate({ boardId: bId, laneId: lId })}
              />
            ))}
          </div>
        </SortableContext>
        <DragOverlay>
          {activeItem?.type === 'card' && <CardDragPreview card={activeItem.item} />}
          {activeItem?.type === 'lane' && <LaneDragPreview lane={activeItem.item} />}
        </DragOverlay>
      </DndContext>
      {canModify && <AddLaneForm boardId={board.id} />}
    </>
  )
}

